from fontTools.ttLib import TTFont
import os

# 修复 maxp 表版本
for font_path in [
    '/root/.codebuddy/artifact/5d808dc5-86f6-400c-8e9c-4969e8827f4c/NotoSansSC-Regular.ttf',
    '/root/.codebuddy/artifact/5d808dc5-86f6-400c-8e9c-4969e8827f4c/NotoSansSC-Bold.ttf'
]:
    font = TTFont(font_path)

    # 修复 maxp 表版本 - reportlab 需要 version 1.0 (0x00010000)
    if 'maxp' in font:
        maxp = font['maxp']
        print(f"{os.path.basename(font_path)}: maxp version = {maxp.tableVersion}")
        # 设置为 1.0 (0x00010000)
        maxp.tableVersion = 0x00010000
        # 确保有必要的字段
        if not hasattr(maxp, 'maxPoints'):
            maxp.maxPoints = 0
        if not hasattr(maxp, 'maxContours'):
            maxp.maxContours = 0
        if not hasattr(maxp, 'maxCompositePoints'):
            maxp.maxCompositePoints = 0
        if not hasattr(maxp, 'maxCompositeContours'):
            maxp.maxCompositeContours = 0
        if not hasattr(maxp, 'maxZone'):
            maxp.maxZone = 2
        if not hasattr(maxp, 'maxTwilightPoints'):
            maxp.maxTwilightPoints = 0
        if not hasattr(maxp, 'maxStorage'):
            maxp.maxStorage = 0
        if not hasattr(maxp, 'maxFunctionDefs'):
            maxp.maxFunctionDefs = 0
        if not hasattr(maxp, 'maxInstructionDefs'):
            maxp.maxInstructionDefs = 0
        if not hasattr(maxp, 'maxStackElements'):
            maxp.maxStackElements = 0
        if not hasattr(maxp, 'maxSizeOfInstructions'):
            maxp.maxSizeOfInstructions = 0
        if not hasattr(maxp, 'maxComponentElements'):
            maxp.maxComponentElements = 0
        if not hasattr(maxp, 'maxComponentDepth'):
            maxp.maxComponentDepth = 0

    # 检查 head 表
    if 'head' in font:
        head = font['head']
        # 确保 magicNumber 正确
        head.magicNumber = 0x5F0F3CF5

    font.save(font_path)
    print(f"  Fixed and saved: {font_path}")

print("Done!")
PYEOF

